mapper.select:
select count(1)
from brm_classroom_borrow
where classroom_id = #{classroomId}
  and borrow_date = #{borrowDate}
  and approve_status in ('0', '1', '2')
  and (start_time is null or end_time is null or #{startTime} is null or #{endTime} is null
       or (start_time < #{endTime} and end_time > #{startTime}))
   and borrow_id != #{excludeBorrowId}
